using UnityEditor;
using UnityEngine;

[CustomEditor(typeof(IslandGenerator))]
public sealed class IslandGeneratorEditor : Editor
{
    public override void OnInspectorGUI()
    {
        serializedObject.Update();
        DrawGeneratorProperties();
        serializedObject.ApplyModifiedProperties();
        serializedObject.Update();
        var island = (IslandGenerator)target;
        EditorGUILayout.Space();
        DrawConfigurationTools(island);
        EditorGUILayout.Space();
        EditorGUILayout.HelpBox(
            "Procedural trees, reeds, rushes, and ferns are generated by the native island pipeline. Decoration prefab libraries remain reserved for later asset-based placement.",
            MessageType.Info);
        using (new EditorGUI.DisabledScope(!Application.isPlaying || island.IsGenerating))
        {
            if (GUILayout.Button("Generate / Regenerate")) island.Generate();
            if (GUILayout.Button("Clear Generated Island")) island.Clear();
        }
        EditorGUILayout.LabelField("Runtime Status", island.Status);
        serializedObject.ApplyModifiedProperties();
    }

    private void DrawGeneratorProperties()
    {
        var property = serializedObject.GetIterator();
        var enterChildren = true;
        while (property.NextVisible(enterChildren))
        {
            enterChildren = false;
            using (new EditorGUI.DisabledScope(property.propertyPath == "m_Script"))
            {
                EditorGUILayout.PropertyField(property, true);
            }
        }
    }

    private void DrawConfigurationTools(IslandGenerator island)
    {
        if (island.Configuration != null)
        {
            EditorGUILayout.HelpBox(
                $"Using island configuration '{island.Configuration.name}'.",
                MessageType.Info);
            if (GUILayout.Button("Select Island Configuration"))
            {
                Selection.activeObject = island.Configuration;
                EditorGUIUtility.PingObject(island.Configuration);
            }
            return;
        }

        EditorGUILayout.HelpBox(
            "This generator requires an IslandConfiguration asset before it can generate.",
            MessageType.Warning);
        if (!GUILayout.Button("Create Island Configuration"))
        {
            return;
        }

        var path = EditorUtility.SaveFilePanelInProject(
            "Create Island Configuration",
            "IslandConfiguration",
            "asset",
            "Choose where to save the reusable island configuration asset.");
        if (string.IsNullOrEmpty(path))
        {
            return;
        }

        var configuration = CreateInstance<IslandConfiguration>();
        AssetDatabase.CreateAsset(configuration, path);
        AssetDatabase.SaveAssets();
        AssetDatabase.ImportAsset(path, ImportAssetOptions.ForceSynchronousImport);
        configuration = AssetDatabase.LoadAssetAtPath<IslandConfiguration>(path);

        var configurationProperty = serializedObject.FindProperty("configuration");
        configurationProperty.objectReferenceValue = configuration;
        serializedObject.ApplyModifiedProperties();
        island.Configure(configuration);
        EditorUtility.SetDirty(island);
        Selection.activeObject = configuration;
        EditorGUIUtility.PingObject(configuration);
    }
}

[CustomEditor(typeof(OceanWaveProfile))]
public sealed class OceanWaveProfileEditor : Editor
{
    public override void OnInspectorGUI()
    {
        serializedObject.Update();

        EditorGUILayout.HelpBox(
            "Tune the broad swells first, then use Wave Shape Noise to break up "
            + "regular crest lines. Fine vertex spacing affects performance; the "
            + "directional wave and noise controls affect appearance.",
            MessageType.Info);

        DrawPropertiesExcluding(serializedObject, "m_Script");
        serializedObject.ApplyModifiedProperties();

        var profile = (OceanWaveProfile)target;
        var settings = profile.ToRuntimeSettings();
        EditorGUILayout.Space();
        EditorGUILayout.LabelField("Calculated Limits", EditorStyles.boldLabel);
        using (new EditorGUI.DisabledScope(true))
        {
            EditorGUILayout.FloatField(
                "Max Height From Mean",
                settings.MaximumVerticalDisplacement);
            EditorGUILayout.FloatField(
                "Max Crest To Trough",
                settings.MaximumVerticalDisplacement * 2f);
            EditorGUILayout.FloatField(
                "Maximum Horizontal Shift",
                settings.MaximumHorizontalDisplacement);
        }

        EditorGUILayout.Space();
        using (new EditorGUI.DisabledScope(!Application.isPlaying))
        {
            if (GUILayout.Button("Apply To Running Ocean"))
            {
                ApplyToRunningOceans(settings);
            }
        }
        if (!Application.isPlaying)
        {
            EditorGUILayout.HelpBox(
                "Enter Play mode to apply changes immediately. Otherwise the "
                + "profile is read the next time the ocean is installed.",
                MessageType.None);
        }
    }

    private static void ApplyToRunningOceans(OceanWaveRuntimeSettings settings)
    {
        var oceans = Object.FindObjectsByType<OceanSurfaceController>(
            FindObjectsInactive.Include);
        var applied = 0;
        foreach (var ocean in oceans)
        {
            if (ocean.SurfaceMaterial == null)
            {
                continue;
            }
            ocean.ApplyWaveSettings(settings);
            applied++;
        }

        Debug.Log($"Applied ocean-wave profile to {applied} running ocean surface(s).");
    }
}
